def components(g):
    H,W=len(g),len(g[0]);seen=set();comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==2 and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));c=[]
                while st:
                    a,b=st.pop();c.append((a,b))
                    for da,db in DIRS:
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==2 and (na,nb) not in seen:
                            seen.add((na,nb));st.append((na,nb))
                comps.append(c)
    return comps
def solve(g,mode,paint_through,stop_at_first):
    H,W=len(g),len(g[0])
    comps=components(g)
    em={tuple(p) for c_ in comps if all(g[p[0]][p[1]]==1 for p in [c_[0]]) or g[c_[0][0]][c_[0][1]]==1}
    # emitters: cells ==1 ; blocks comps of 2
    ones={(i,j) for i in range(H) for j in range(W) if g[i][j]==1}
    em=list(ones); bl=[set(c_) for c_ in components(g) if g[next(iter(c_))[0]][next(iter(c_))[1]]==2]
    out=[row[:] for row in g]; painted=set()
    for ei,ej in em:
        for di,dj in DIRS:
            i_,j_=ei+di,ej+dj; blocked=False
            while 0<=i_<H and 0<=j_<W:
                v=g[i_][j_]
                if v==2:
                    blk=[c_ for c_ in bl if (i_,j_) in c_][0]
                    if mode=='full':
                        for (r,c) in blk: painted.add((r,c))
                    else: pass
                    if stop_at_first: break
                    i_,j_=blk.__next__() if False else (i_+di,j_+dj)
                    continue
                painted.add((i_,j_))
                i_,j_+=di,dj
            if mode=='through': pass
    # also full-block painting: mark block comps containing painted cells entirely when any cell painted -> whole comp
    for blk in bl:
        if any(p in blk for p in painted):
            for p in blk: painted.add(p)
    for i,j in painted: out[i][j]=1
    return out
