        if min(cs)==0 and max(cs)==W-1:
            for j in range(W): line_cells.add((r_,j))
    for c_,rs in bycol.items():
        if min(rs)==0 and max(rs)==H-1:
            for i in range(H): line_cells.add((i,c_))
    # paint zeros on full lines
    for (r_,c_) in line_cells:
        if gi[r_][c_]==0: o[r_][c_]=1
    # convert whole blocks intersecting a full line
    for b in bls:
        if any(p in line_cells for p in b):
            for i,j in b: o[i][j]=1
    return o
