def solve_contact(gi):
    H,W=len(gi),len(gi[0])
    E=[(i,j) for i in range(H) for j in range(W) if gi[i][j]==1]
    byrow={};bycol={}
    for i,j in E: byrow.setdefault(i,[]).append(j); bycol.setdefault(j,[]).append(i)
    lines=[]
    # full-span lines + partial aligned-pair lines
    for r_,cs in byrow.items():
        lo,hi=min(cs),max(cs)
        if hi-lo+1==W or len(cs)>=2: lines.append(('h',r_,lo,hi))
    for c_,rs in bycol.items():
        lo,hi=min(rs),max(rs)
        if hi-lo+1==H or len(rs)>=2: lines.append(('v',c_,lo,hi))
    o=[r[:] for r in gi]; bls=blocks_of(gi)
    line_cells=set()
    for t,pos,lo,hi in lines:
        rng=[(pos,j) for j in range(lo,hi+1)] if t=='h' else [(i,pos) for i in range(lo,hi+1)]
        for p in rng: line_cells.add(p)
    for (r_,c_) in line_cells:
        if gi[r_][c_]==0: o[r_][c_]=1
    touch=set()
    for b in bls:
        if any(p in line_cells for p in b): touch.update(b)
    for i,j in touch: o[i][j]=1
    return o
