def solve_span(gi):
    H,W=len(gi),len(gi[0])
    o=[r[:] for r in gi]
    # collect candidate lines: any pair of emitters in same row/col paints the segment BETWEEN them
    E=[(i,j) for i in range(H) for j in range(W) if gi[i][j]==1]
    bls=blocks_of(gi)
    line=set()
    for (a,b) in [(p,q) for idx,(p,q) in enumerate(E) for _ in [None]]:
        pass
    # simpler: for each unordered pair, fill segment if collinear
    for i1 in range(len(E)):
        for i2 in range(i1+1,len(E)):
            (r1,c1),(r2,c2)=E[i1],E[i2]
            if r1==r2:
                lo,hi=min(c1,c2),max(c1,c2)
                for c_ in range(lo,hi+1): line.add((r1,c_))
            elif c1==c2:
                lo,hi=min(r1,r2),max(r1,r2)
                for r_ in range(lo,hi+1): line.add((r_,c1))
    for (r_,c_) in line:
        if gi[r_][c_]==0: o[r_][c_]=1
    for b in bls:
        if any(p in line for p in b):
            for i,j in b: o[i][j]=1
    return o
